diff --git a/src/ui/glyph_cache.h b/src/ui/glyph_cache.h
index a440f82..28f126e 100644
--- a/src/ui/glyph_cache.h
+++ b/src/ui/glyph_cache.h
@@ -6,7 +6,8 @@

 // Glyphs rasterise on first use at the exact pixel size into RGBA8 atlas pages: white, with coverage in alpha.
 // Colour emoji share the pages, resampled to a Font Size square.
-// When every page is full, the least recently used one is cleared; one used this frame is never cleared.
+// When every page is full, the least recently used one is cleared; one used this frame is never cleared, so a glyph
+// that finds no room waits for a later frame and draws as a missing-glyph box until then.
 #define VD_GLYPH_ATLAS_PAGE_SIZE 1024
 #define VD_GLYPH_ATLAS_PAGE_BYTES (VD_GLYPH_ATLAS_PAGE_SIZE * VD_GLYPH_ATLAS_PAGE_SIZE * 4)
 #define VD_GLYPH_ATLAS_PAGE_MAX 4
@@ -27,7 +28,8 @@ typedef struct {
 } VdGlyphFontMetrics;

 typedef struct {
-    // -1 when the glyph has no pixels, like a space, or found no room this frame.
+    // -1 when the glyph has no pixels, like a space, or found no room this frame; then width and height, if set, are
+    // the box to draw in its place.
     int page;
     int x, y, width, height;
     // From the pen position on the baseline to the bitmap's top-left corner.
@@ -52,6 +63,8 @@ typedef struct {
     int pages;
     int glyphs;
     int rasterised;
+    // Lookups this frame that found no room in the atlas.
+    int overflowed;
 } VdGlyphCacheStats;

 // TrueType or OpenType; NULL when the file is missing or not a font.

diff --git a/src/ui/text.c b/src/ui/text.c
index aac80fd..5d1525d 100644
--- a/src/ui/text.c
+++ b/src/ui/text.c
@@ -8,6 +8,7 @@
 #define TEXT_SPACING 1.0f

 static Texture2D g_page_textures[VD_GLYPH_ATLAS_PAGE_MAX];
+static bool g_overflow_warned = false;

 void text_begin_frame(void)
 {
@@ -26,6 +27,12 @@ void text_reset(void)
 // Once per frame, before drawing: vitaGL copies the whole texture when one already drawn this frame changes.
 void text_upload_pages(void)
 {
+    int overflowed = glyph_cache_stats().overflowed;
+    if (overflowed > 0 && !g_overflow_warned) {
+        TraceLog(LOG_WARNING, "TEXT: This frame needs more glyphs than %d atlas pages hold; %d draw as boxes",
+                 VD_GLYPH_ATLAS_PAGE_MAX, overflowed);
+        g_overflow_warned = true;
+    }
     for (int page = 0; page < VD_GLYPH_ATLAS_PAGE_MAX; page++) {
         const unsigned char *pixels = glyph_cache_take_dirty_page(page);
         if (!pixels) continue;
@@ -130,11 +137,13 @@ void text_draw(const VdFont *font, const char *text, Vector2 position, int font_
         if (!cluster.emoji && draws_nothing(cluster.codepoint)) continue;

         VdGlyph glyph = cluster.emoji ? cluster.glyph : glyph_cache_get(font->outline, font_size, cluster.codepoint);
+        Vector2 at = {roundf(pen) + (float)glyph.offset_x, baseline + (float)glyph.offset_y};
         if (glyph.page >= 0 && IsTextureValid(g_page_textures[glyph.page])) {
             Rectangle source = {(float)glyph.x, (float)glyph.y, (float)glyph.width, (float)glyph.height};
-            Vector2 at = {roundf(pen) + (float)glyph.offset_x, baseline + (float)glyph.offset_y};
             Color tint = glyph.color ? (Color){255, 255, 255, color.a} : color;
             DrawTextureRec(g_page_textures[glyph.page], source, at, tint);
+        } else if (glyph.page < 0 && glyph.width > 0) {
+            DrawRectangleLines((int)at.x, (int)at.y, glyph.width, glyph.height, color);
         }
         pen += glyph.advance + TEXT_SPACING;
     }

diff --git a/tests/glyph_cache_harness.c b/tests/glyph_cache_harness.c
index 321285c..f960509 100644
--- a/tests/glyph_cache_harness.c
+++ b/tests/glyph_cache_harness.c
@@ -422,8 +501,22 @@ static void test_pages(const VdGlyphFont *full)
     expect(pages_in_order, "pages fill one after another");
     expect(glyph_cache_stats().pages == VD_GLYPH_ATLAS_PAGE_MAX, "pages grow up to the cap");
     expect(refused != 0, "with every page used this frame, a new glyph waits for a later frame");
+    VdGlyph box = glyph_cache_get(full, size, refused);
+    expect(box.page == -1 && box.width > 0 && box.height > 0, "a glyph with no room is a box to draw in its place");
+    expect(glyph_cache_stats().overflowed == 2, "each lookup with no room counts as overflow");
     int glyphs_before = glyph_cache_stats().glyphs;

+    glyph_cache_begin_frame();
+    expect(glyph_cache_stats().overflowed == 0, "a frame starts without overflow");
+    int rasterised_before = glyph_cache_stats().rasterised;
+    for (uint32_t codepoint = first; codepoint <= refused; codepoint++) {
+        if (codepoint >= 0x7f && codepoint < 0xa1) continue;
+        glyph_cache_get(full, size, codepoint);
+    }
+    expect(glyph_cache_stats().rasterised == rasterised_before,
+           "repeating an overflowing frame keeps its glyphs instead of clearing pages it draws from");
+    expect(glyph_cache_stats().overflowed == 1, "repeating an overflowing frame overflows the same way");
+
     glyph_cache_begin_frame();
     VdGlyph placed = glyph_cache_get(full, size, refused);
     expect(placed.page == 0, "a later frame clears the least recently used page");
